public boolean validate()
{
    boolean ret;

    ret = next validate()
        && this.ACIsFantasyBook();

    return ret;
}

private boolean ACIsFantasyBook()
{
    SalesTable salesTable = this.dataSource().cursor();

    if(ACBookTable::findRecId(salesTable.ACBookTable).Genre != ACGenreEnum::Fantasy)
    {
        return checkFailed("@ACItFormacionLabels:YouMustSelectFantasyBooks");
    }

    return true;
}
